param([Parameter(Mandatory=$true)][string]$Dataset)
$ErrorActionPreference='Stop';$root=Split-Path $PSScriptRoot -Parent;$image=(Get-Content -Raw (Join-Path $root '.local/media-processing/image.json')|ConvertFrom-Json).id;$rows=@()
$limits=@('--init','--user','1000:1000','--read-only','--cap-drop','ALL','--security-opt','no-new-privileges:true','--pids-limit','64','--cpus','1','--memory','512m','--memory-swap','512m','--tmpfs','/scratch:size=128m,uid=1000,gid=1000,mode=0700','--tmpfs','/tmp:size=16m,uid=1000,gid=1000,mode=0700','--network','none')
function D([string[]]$a){$o=& docker @a;if($LASTEXITCODE -ne 0){throw 'Scoped fault operation failed'};return $o}
foreach($fault in @('IO_AFTER_THUMBNAIL','CANCELLATION','SUBPROCESS_TIMEOUT')){$id=$null;$start=[DateTime]::UtcNow;$timeline=@();$input=Join-Path $Dataset ('inputs/'+$(if($fault -eq 'IO_AFTER_THUMBNAIL'){'MP4-H264-NO-AUDIO.mp4'}else{'duration-300.mp4'}));$before=(Get-FileHash -LiteralPath $input -Algorithm SHA256).Hash.ToLowerInvariant();
try{$name='el061-fault-'+[guid]::NewGuid().ToString('N');$cmd=if($fault -eq 'IO_AFTER_THUMBNAIL'){ $arg=[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes('{"format":"MP4","outcome":"ACCEPT","fault":"IO_AFTER_THUMBNAIL"}'));@('/code/parser.mjs',$arg)}else{@('/code/supplemental-fault.mjs',$(if($fault -eq 'SUBPROCESS_TIMEOUT'){'timeout'}else{'cancel'}))};$id=(D (@('run','--detach','--name',$name,'--label','eventlens.spike=061-supplemental-fault')+$limits+@('--mount',"type=bind,source=$PSScriptRoot,target=/code,readonly",'--mount',"type=bind,source=$input,target=/input,readonly",'--entrypoint','node',$image)+$cmd)).Trim();$timeline+=@{event='isolated-media-attempt-start';at=[DateTime]::UtcNow.ToString('o')}
if($fault -eq 'CANCELLATION'){do{& docker exec $id test -f /scratch/fault-ready.json 2>$null;if($LASTEXITCODE -eq 0){break};if(([DateTime]::UtcNow-$start).TotalSeconds -gt 10){throw 'Media process failed to start'};Start-Sleep -Milliseconds 100}while($true);$ready=(D @('exec',$id,'cat','/scratch/fault-ready.json'))|ConvertFrom-Json;Start-Sleep -Milliseconds 1800;$stat=(D @('exec',$id,'sh','-c','stat -c %s /scratch/partial.mp4; test -e /proc/' + $ready.pid + '/status'))[0];$timeline+=@{event='actual-ffmpeg-running-private-partial';at=[DateTime]::UtcNow.ToString('o');pid=$ready.pid;partialBytes=[int]$stat};D @('kill','--signal','KILL',$id)|Out-Null;$state=(D @('inspect','--format','{{json .State}}',$id))|ConvertFrom-Json;if($state.Running){throw 'Container still running'};$timeline+=@{event='container-kill-observed-no-media-process';at=[DateTime]::UtcNow.ToString('o')};$detail=@{mediaPid=$ready.pid;partialBytes=[int]$stat;containerStopped=$true;publishedOutputs=0;attemptResult='CANCELLED'};
}else{do{& docker exec $id test -f /scratch/result.json 2>$null;if($LASTEXITCODE -eq 0){break};if(([DateTime]::UtcNow-$start).TotalSeconds -gt 50){throw 'Fault did not finish boundedly'};Start-Sleep -Milliseconds 200}while($true);$detail=(D @('exec',$id,'cat','/scratch/result.json'))|ConvertFrom-Json;if($detail.outcome -ne 'PROCESSING_FAILED' -or $detail.outputs.Count -ne 0){throw 'Runtime fault misclassified or partial exported'};if($fault -eq 'IO_AFTER_THUMBNAIL'){$trigger=(D @('exec',$id,'cat','/scratch/fault-triggered.json'))|ConvertFrom-Json;if(-not $trigger.partialExisted){throw 'Partial thumbnail did not precede IO fault'};if($detail.failureKind -ne 'PROCESSING_FAILURE' -or $detail.failureDetails.reason -ne 'OUTPUT_OR_RUNTIME_IO' -or $detail.failureDetails.operation -ne 'OUTPUT_TRANSFORM'){throw 'Injected fault lacks actual output-open IO classification'};D @('exec',$id,'sh','-c','test ! -f /scratch/thumbnail.jpg; test ! -f /scratch/playback.mp4')|Out-Null}else{D @('exec',$id,'sh','-c','test ! -f /scratch/partial.mp4; ! pgrep ffmpeg')|Out-Null};$timeline+=@{event='runtime-fault-no-exportable-partials';at=[DateTime]::UtcNow.ToString('o')};}
$after=(Get-FileHash -LiteralPath $input -Algorithm SHA256).Hash.ToLowerInvariant();if($before -ne $after){throw 'Original changed'};$rows+=@{fault=$fault;result='PASS';timeline=$timeline;detail=$detail;originalSha256Before=$before;originalSha256After=$after;elapsedMs=([DateTime]::UtcNow-$start).TotalMilliseconds;outputsPromoted=0}
}catch{$rows+=@{fault=$fault;result='FAIL';safeError='Bounded injected fault failed';exceptionClass=$_.Exception.Message;timeline=$timeline}}finally{if($id){D @('rm','--force',$id)|Out-Null;$remaining=D @('ps','-aq','--filter',"name=^/$name$");if($remaining){throw 'Attempt cleanup failed'}}};[IO.File]::WriteAllText((Join-Path $Dataset 'faults.json'),($rows|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));Write-Output "FAULT $fault $($rows[-1].result)"}
